from html.parser import HTMLParser
from pathlib import Path

html = Path('index.html').read_text()

class Parser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.inputs = {}
        self.labels_for = set()
        self.form_field_divs = 0
        self.phone_helper = False
        self.submit_button = False
        self.main_count = 0
        self.h1_count = 0
        self.errors = []
    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        self.stack.append((tag, attrs))
        if tag == 'main':
            self.main_count += 1
        if tag == 'h1':
            self.h1_count += 1
        if tag == 'div' and 'form-field' in attrs.get('class', '').split():
            self.form_field_divs += 1
        if tag == 'label' and 'for' in attrs:
            self.labels_for.add(attrs['for'])
        if tag == 'input':
            self.inputs[attrs.get('id')] = attrs
        if tag == 'p' and attrs.get('id') == 'phone-helper':
            self.phone_helper = True
        if tag == 'button' and attrs.get('type') == 'submit':
            self.submit_button = True
    def handle_endtag(self, tag):
        if self.stack:
            self.stack.pop()

p = Parser(); p.feed(html)
required = {
    'full-name': ('text', True),
    'email': ('email', True),
    'phone': ('tel', False),
}
for field_id, (field_type, is_required) in required.items():
    attrs = p.inputs.get(field_id)
    if not attrs:
        p.errors.append(f'missing input #{field_id}')
        continue
    if attrs.get('type') != field_type:
        p.errors.append(f'#{field_id} expected type {field_type}, got {attrs.get("type")}')
    if field_id not in p.labels_for:
        p.errors.append(f'#{field_id} missing label')
    if ('required' in attrs) != is_required:
        p.errors.append(f'#{field_id} required mismatch')
    if 'aria-describedby' not in attrs:
        p.errors.append(f'#{field_id} missing aria-describedby')
if p.form_field_divs != 3:
    p.errors.append(f'expected 3 .form-field divs, got {p.form_field_divs}')
if not p.phone_helper:
    p.errors.append('missing phone helper text')
if not p.submit_button:
    p.errors.append('missing submit button')
if p.main_count != 1 or p.h1_count != 1:
    p.errors.append(f'expected one main and one h1, got main={p.main_count}, h1={p.h1_count}')
for token in ['addEventListener("submit"', 'aria-invalid', 'Enter your full name', 'Enter an email address', '10-digit phone number']:
    if token not in html:
        p.errors.append(f'missing validation token: {token}')
if p.errors:
    print('\n'.join(p.errors))
    raise SystemExit(1)
print('structure checks passed')
