       <form id="support-form" novalidate>
         <div class="form-field">
           <label for="full-name">Full name <span aria-hidden="true">*</span></label>
           <input
             id="full-name"
             name="full-name"
             type="text"
             autocomplete="name"
             required
             aria-describedby="full-name-error"
           >
           <p class="error-message" id="full-name-error" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="email">Email address <span aria-hidden="true">*</span></label>
           <input
             id="email"
             name="email"
             type="email"
             autocomplete="email"
             inputmode="email"
             required
             aria-describedby="email-error"
           >
           <p class="error-message" id="email-error" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="phone">Phone number <span class="required-note">(optional)</span></label>
           <input
             id="phone"
             name="phone"
             type="tel"
             autocomplete="tel"
             inputmode="tel"
             aria-describedby="phone-helper phone-error"
             placeholder="555-123-4567"
           >
           <p class="helper-text" id="phone-helper">Use 10 digits, such as 555-123-4567.</p>
           <p class="error-message" id="phone-error" aria-live="polite"></p>
         </div>

         <div class="form-actions">
           <button type="submit">Submit support request</button>
           <p class="status-message" id="form-status" aria-live="polite"></p>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#support-form");
     const statusMessage = document.querySelector("#form-status");
     const fields = {
       fullName: {
         input: document.querySelector("#full-name"),
         error: document.querySelector("#full-name-error"),
         validate(value) {
           if (!value.trim()) {
             return "Enter your full name.";
           }

           return "";
         }
       },
       email: {
         input: document.querySelector("#email"),
         error: document.querySelector("#email-error"),
         validate(value) {
           const trimmedValue = value.trim();
           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

           if (!trimmedValue) {
             return "Enter your email address.";
           }

           if (!emailPattern.test(trimmedValue)) {
             return "Enter an email address in the format name@example.com.";
           }

           return "";
         }
       },
       phone: {
         input: document.querySelector("#phone"),
         error: document.querySelector("#phone-error"),
         validate(value) {
           const trimmedValue = value.trim();
           const phonePattern = /^\d{3}[-.\s]?\d{3}[-.\s]?\d{4}$/;

           if (trimmedValue && !phonePattern.test(trimmedValue)) {
             return "Enter a 10-digit phone number, such as 555-123-4567.";
           }

           return "";
         }
       }
     };

     function setFieldError(field, message) {
       field.error.textContent = message;
       field.input.setAttribute("aria-invalid", message ? "true" : "false");
     }

     function validateField(field) {
       const message = field.validate(field.input.value);
       setFieldError(field, message);
       return !message;
     }

     Object.values(fields).forEach((field) => {
       field.input.addEventListener("blur", () => validateField(field));
       field.input.addEventListener("input", () => {
         statusMessage.textContent = "";
         if (field.input.getAttribute("aria-invalid") === "true") {
           validateField(field);
         }
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const firstInvalidField = Object.values(fields).find((field) => !validateField(field));

       if (firstInvalidField) {
         statusMessage.textContent = "";
         firstInvalidField.input.focus();
         return;
       }

       statusMessage.textContent = "Thanks. Your support request is ready to submit.";
       form.reset();
       Object.values(fields).forEach((field) => setFieldError(field, ""));
     });
   </script>
 </body>
 </html>

